/**
 * @brief SHOW VERSION: board ID, register map, build ID and tree state,
 *        network capability, firmware name and build date.
 * @param ctx Unused.
 * @return 0, or -1 when the board system registers do not answer.
 */
int cli_show_version(const MenuCommandContext *ctx)
{
    uint32_t id  = board_sys_read(ETHS_SYS_ID);
    uint32_t ver = board_sys_read(ETHS_SYS_VERSION);
    uint32_t bid = board_sys_read(ETHS_SYS_BUILD_ID);
    uint32_t dty = board_sys_read(ETHS_SYS_BUILD_DIRTY) & 1u;
    uint32_t brd = board_sys_read(ETHS_SYS_BOARD_ID);
    uint32_t cap = board_sys_read(ETHS_SYS_CAPS);
    uint32_t lc  = board_link_caps();
    char idt[5];
    char brdt[5];
    (void)ctx;
    board_id_text(id, idt);
    board_id_text(brd, brdt);
    fmt_printf("RTLNet Ethernet demo\n");
    fmt_printf("  System block    : %s (0x%08X)%s\n", idt, (unsigned)id,
               (id == ETHS_SYS_ID_VALUE) ? "" : "  % unexpected, system registers not found");
    fmt_printf("  Register map    : ");
    cli_print_datecode(ver);
    fmt_printf(" (0x%08X)\n", (unsigned)ver);
    fmt_printf("  Board           : %s (0x%08X), %u LEDs, %u switches, %u buttons\n", brdt, (unsigned)brd,
               (unsigned)((cap >> ETHS_CAPS_NUM_LEDS_SHIFT) & 0xFFu), (unsigned)((cap >> ETHS_CAPS_NUM_SW_SHIFT) & 0xFFu),
               (unsigned)((cap >> ETHS_CAPS_NUM_BTN_SHIFT) & 0xFFu));
    fmt_printf("  CPU clock       : %u Hz\n", (unsigned)board_sys_read(ETHS_SYS_CPU_CLK_HZ));
    fmt_printf("  Link modes      : %s%s%s (full duplex)\n", (lc & ETHS_LINK_10F) ? "10 " : "",
               (lc & ETHS_LINK_100F) ? "100 " : "", (lc & ETHS_LINK_1000F) ? "1000 " : "");
    fmt_printf("  Build ID        : 0x%08x (git %08x), tree %s\n", (unsigned)bid, (unsigned)bid, dty ? "dirty" : "clean");
    rtlnet_features_discover();
    fmt_printf("  CPU path blocks : classifier %s, checksum offload TX %s, RX %s%s\n",
               rtlnet_features()->cls_present ? "yes" : "no", rtlnet_features()->tx_present ? "yes" : "no",
               rtlnet_features()->rx_present ? "yes" : "no",
               rtlnet_features()->errors ? "  % discovery mismatch, see show offload" : "");
    fmt_printf("  Firmware        : %s %s, built %s %s\n", RTLNET_FW_NAME, RTLNET_FW_VERSION, __DATE__, __TIME__);
    return (id == ETHS_SYS_ID_VALUE) ? 0 : -1;
}

/**
 * @brief SHOW SYSTEM: uptime, CPU clock, switches, buttons, LEDs, PHY pins and
 *        network status levels.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_system(const MenuCommandContext *ctx)
{
    static const char btn_names[5] = { 'C', 'D', 'L', 'R', 'U' };
    uint32_t cs   = board_sys_read(ETHS_SYS_CLK_STATUS);
    uint32_t up   = board_sys_read(ETHS_SYS_UPTIME_MS);
    uint32_t hz   = board_sys_read(ETHS_SYS_CPU_CLK_HZ);
    uint32_t sw   = board_sys_read(ETHS_SYS_SWITCHES) & 0xFFu;
    uint32_t btn  = board_sys_read(ETHS_SYS_BUTTONS) & 0x1Fu;
    uint32_t leds = board_sys_read(ETHS_SYS_LEDS) & 0xFFu;
    uint32_t phy  = board_sys_read(ETHS_SYS_PHY_STATUS);
    uint32_t net  = board_sys_read(ETHS_SYS_NET_STATUS);
    uint32_t s    = up / 1000u;
    (void)ctx;

    fmt_printf("System\n");
    fmt_printf("  Clocks          : %s\n", (cs & ETHS_CLK_LOCKED) ? "locked" : "NOT locked");
    fmt_printf("  Uptime          : %ud %02u:%02u:%02u.%03u (%u ms since reset release; firmware %u ms)\n",
               (unsigned)(s / 86400u), (unsigned)((s / 3600u) % 24u), (unsigned)((s / 60u) % 60u),
               (unsigned)(s % 60u), (unsigned)(up % 1000u), (unsigned)up, (unsigned)plat_uptime_ms());
    fmt_printf("  CPU clock       : %u Hz\n", (unsigned)hz);
    fmt_printf("  Switches        : 0x%02X  (sw7..sw0 =", (unsigned)sw);
    for (int b = 7; b >= 0; b--) {
        fmt_printf(" %u", (unsigned)((sw >> b) & 1u));
    }
    fmt_printf(")\n  Buttons         : 0x%02X  (", (unsigned)btn);
    for (unsigned b = 0; b < 5u; b++) {
        fmt_printf("%c=%u%s", btn_names[b], (unsigned)((btn >> b) & 1u), (b < 4u) ? " " : ")\n");
    }
    fmt_printf("  LEDs            : 0x%02X  (led0 clocks locked, led1 heartbeat, led2 link, led3 DHCP lease)\n",
               (unsigned)(leds | ((cs & 1u) ? 1u : 0u)));
    fmt_printf("  PHY pins        : rst_n=%u int_n=%u mdio=%u\n", (unsigned)((phy & ETHS_PHY_RST_N) != 0u),
               (unsigned)((phy & ETHS_PHY_INT_N) != 0u), (unsigned)((phy & ETHS_PHY_MDIO_IN) != 0u));
    fmt_printf("  Network status  : link_up=%u speed=%u rx_clk_ok=%u ip_valid=%u dhcp_bound=%u\n",
               (unsigned)((net & ETHS_NET_LINK_UP) != 0u), (unsigned)((net & ETHS_NET_SPEED_MASK) >> ETHS_NET_SPEED_SHIFT),
               (unsigned)((net & ETHS_NET_RX_CLK_OK) != 0u), (unsigned)((net & ETHS_NET_IP_VALID) != 0u),
               (unsigned)((net & ETHS_NET_DHCP_BOUND) != 0u));
    return 0;
}

/**
 * @brief SHOW INTERFACES: link monitor state, MAC status and counters, and
 *        the eth0 configuration.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_interfaces(const MenuCommandContext *ctx)
{
    const netmgr_link_t *l = netmgr_link();
    const netmgr_config_t *c = netmgr_config();
    rtlnet_eth_mac_status_t st;
    rtlnet_eth_mac_counters_t k;
    (void)ctx;
    if (!cli_core_check(&g_core_mac)) {
        return 0;
    }
    rtlnet_eth_mac_read_status(RTLNET_PLAT_MAC_BASE, &st);
    rtlnet_eth_mac_read_counters(RTLNET_PLAT_MAC_BASE, &k);
    fmt_printf("eth0 is %s%s", l->up ? "up" : "down", c->shutdown ? " (administratively shut down)" : "");
    if (l->up) {
        fmt_printf(", %u Mb/s %s duplex", (unsigned)l->speed_mbps, l->full_duplex ? "full" : "half");
    }
    fmt_printf(", link changes up %u / down %u\n", (unsigned)l->ups, (unsigned)l->downs);
    fmt_printf("  MAC speed       : %u Mb/s in effect, RXC %s (rate %u), IDELAY %s, receive path %s\n",
               (unsigned)st.speed_mbps, st.rx_clk_ok ? "ok" : "not qualified", (unsigned)st.rx_clk_rate,
               st.idelay_rdy ? "ready" : "not ready", st.rx_in_reset ? "in reset" : "running");
    fmt_printf("  In-band status  : link %u, %u Mb/s, %s duplex (debug)\n", (unsigned)st.inband_link,
               (unsigned)st.inband_speed_mbps, st.inband_full_duplex ? "full" : "half");
    fmt_printf("  Frames          : rx good %u, rx bad %u, rx overflow %u, tx %u\n", (unsigned)k.rx_good,
               (unsigned)k.rx_bad, (unsigned)k.rx_overflow, (unsigned)k.tx_frames);
    fmt_printf("  Configuration   : speed %s\n", cli_speed_text(netmgr_adv_effective()));
    return 0;
}

/**
 * @brief SHOW PHY: PHY identity, RX delay, BMCR/BMSR/PHYSR, link, own and
 *        partner advertisement.
 * @param ctx Unused.
 * @return 0, or -1 on an MDIO error.
 */
int cli_show_phy(const MenuCommandContext *ctx)
{
    const rtlnet_mdio_t *m = cli_phy_bus();
    const netmgr_present_t *p = netmgr_present();
    rtlnet_phy_status_t st;
    uint32_t adv = 0u;
    int rc;
    (void)ctx;
    if (m == NULL) {
        return 0;
    }
    if (!p->phy) {
        fmt_printf("%% No PHY answered on the MDIO bus\n");
        return 0;
    }
    fmt_printf("PHY at MDIO address %u: ID 0x%08X, driver %s, MDC half period %u ns\n", (unsigned)p->phy_addr,
               (unsigned)p->phy_id, p->phy_driver->name, (unsigned)p->mdc_half_ns);
    fmt_printf("  Bring-up        : %s (result %d)\n", p->phy_summary, p->phy_rc);
    rc = p->phy_driver->status(m, &st);
    if (rc != RTLNET_PHY_OK) {
        return cli_rc("PHY status read", rc);
    }
    (void)p->phy_driver->advertise_get(m, &adv);
    fmt_printf("  Registers       : BMCR 0x%04X  BMSR 0x%04X  PHYSR 0x%04X  ANLPAR 0x%04X  GBSR 0x%04X\n",
               (unsigned)st.bmcr, (unsigned)st.bmsr, (unsigned)st.physr, (unsigned)st.anlpar, (unsigned)st.gbsr);
    fmt_printf("  Link            : %s", st.link_up ? "up" : "down");
    if (st.speed_valid) {
        fmt_printf(", %u Mb/s %s duplex", (unsigned)rtlnet_phy_speed_mbps(st.speed), st.full_duplex ? "full" : "half");
    }
    fmt_printf("\n  Auto-negotiation: %s, %s\n", st.an_enabled ? "enabled" : "disabled (forced)",
               st.an_complete ? "complete" : "not complete");
    fmt_printf("  Advertised      : ");
    cli_print_adv(adv);
    fmt_printf("\n  Partner         : ");
    cli_print_adv(st.partner_adv);
    fmt_printf("\n");
    if (p->phy_driver->show_details != NULL) {
        p->phy_driver->show_details(m);
    }
    return 0;
}

/**
 * @brief SHOW IP: node MAC, static and effective addresses, DHCP use.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_ip(const MenuCommandContext *ctx)
{
    uint8_t mac[6];
    char a[16];
    char b[16];
    char g[16];
    char mt[18];
    uintptr_t base = RTLNET_PLAT_PROT_BASE;
    (void)ctx;
    if (!cli_core_check(&g_core_prot)) {
        return 0;
    }
    rtlnet_eth_protocol_get_mac(base, mac);
    fmt_printf("Node MAC          : %s, destination filter %s\n", cli_mac_text(mac, mt),
               rtlnet_eth_protocol_get_filter_enable(base) ? "on" : "off (promiscuous)");
    fmt_printf("Effective IPv4    : %s mask %s gateway %s (%s)\n",
               cli_ipv4_text(rtlnet_eth_protocol_get_effective_ip(base), a),
               cli_ipv4_text(rtlnet_eth_protocol_get_effective_mask(base), b),
               cli_ipv4_text(rtlnet_eth_protocol_get_effective_gateway(base), g),
               rtlnet_eth_protocol_ip_from_dhcp(base) ? "DHCP lease" : "static");
    fmt_printf("Static IPv4       : %s mask %s gateway %s\n", cli_ipv4_text(rtlnet_eth_protocol_get_static_ip(base), a),
               cli_ipv4_text(rtlnet_eth_protocol_get_netmask(base), b),
               cli_ipv4_text(rtlnet_eth_protocol_get_gateway(base), g));
    fmt_printf("Leaves present    : 0x%02X, enabled 0x%02X (bit 0 UDP, 1 ICMP, 2 ARP, 3 DHCP, 4 iperf)\n",
               (unsigned)rtlnet_eth_protocol_get_leaves_present(base),
               (unsigned)rtlnet_eth_protocol_get_leaf_enables(base));
    return 0;
}

/**
 * @brief SHOW ARP: ARP responder counters.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_arp(const MenuCommandContext *ctx)
{
    rtlnet_arp_counters_t k;
    (void)ctx;
    if (!cli_core_check(&g_core_arp)) {
        return 0;
    }
    rtlnet_arp_read_counters(RTLNET_PLAT_ARP_BASE, &k);
    fmt_printf("ARP responder %s: requests for us %u, replies sent %u, ignored %u, reply delay %u proto_clk cycles\n",
               (rtlnet_arp_get_status(RTLNET_PLAT_ARP_BASE) & RTLNET_ARP_STATUS_ENABLED) ? "enabled" : "disabled",
               (unsigned)k.requests_for_us, (unsigned)k.replies_sent, (unsigned)k.ignored,
               (unsigned)rtlnet_arp_get_reply_delay_cycles(RTLNET_PLAT_ARP_BASE));
    return 0;
}

/**
 * @brief SHOW DHCP: client state, lease and counters.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_dhcp(const MenuCommandContext *ctx)
{
    rtlnet_dhcp_lease_t l;
    rtlnet_dhcp_counters_t k;
    char a[16];
    char m[16];
    char r[16];
    char s[16];
    (void)ctx;
    if (!cli_core_check(&g_core_dhcp)) {
        return 0;
    }
    (void)rtlnet_dhcp_read_lease(RTLNET_PLAT_DHCP_BASE, &l);
    (void)rtlnet_dhcp_read_counters(RTLNET_PLAT_DHCP_BASE, &k);
    fmt_printf("DHCP client: state %s%s%s, auto-start %s, xid 0x%08X\n", rtlnet_dhcp_state_name(l.state),
               l.bound ? ", bound" : "", l.fail ? ", last attempt failed" : "", l.auto_start ? "on" : "off",
               (unsigned)l.xid);
    if (l.bound) {
        fmt_printf("  Lease           : %s mask %s router %s server %s\n", cli_ipv4_text(l.lease_ip, a),
                   cli_ipv4_text(l.lease_mask, m), cli_ipv4_text(l.lease_router, r), cli_ipv4_text(l.lease_server, s));
        fmt_printf("  Lease time      : %u s, elapsed %u s\n", (unsigned)l.lease_time_s, (unsigned)l.lease_elapsed_s);
    }
    fmt_printf("  Counters        : discover %u, offer %u, request %u, ack %u, nak %u, lost %u, release %u\n",
               (unsigned)k.discovers_sent, (unsigned)k.offers_rx, (unsigned)k.requests_sent, (unsigned)k.acks_rx,
               (unsigned)k.naks_rx, (unsigned)k.leases_lost, (unsigned)k.releases_sent);
    return 0;
}

/**
 * @brief Print one TCP iperf test: direction, result, peer, bytes, duration, throughput.
 * @param label Left column text.
 * @param t     The test; result NONE prints "none yet".
 */
static void cli_tcp_iperf_test_line(const char *label, const rtlnet_tcp_iperf_test_t *t)
{
    char a[16];
    if (t->result == RTLNET_TCP_IPERF_NONE) {
        fmt_printf("  %s: none yet\n", label);
        return;
    }
    fmt_printf("  %s: %s, %s, peer %s:%u, %u bytes in %u ms, %u kbit/s\n", label, rtlnet_tcp_iperf_dir_name(t->dir),
               rtlnet_tcp_iperf_result_name(t->result), cli_ipv4_text(t->remote_ip, a), (unsigned)t->remote_port,
               (unsigned)t->bytes, (unsigned)t->ms, (unsigned)t->kbps);
}

/**
 * @brief SHOW IPERF: the two iperf servers. "UDP (RTL core)": port and the
 *        last flow of the iperf leaf. "TCP (firmware, lwIP)": the rtlnet_lwiperf
 *        server, its last two test reports with direction (pc->board, reverse
 *        -R, tradeoff -r, dual -d) and the test counts.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_iperf(const MenuCommandContext *ctx)
{
    rtlnet_iperf_stats_t st;
    rtlnet_tcp_iperf_status_t t;
    (void)ctx;
    fmt_printf("UDP (RTL core)\n");
    if (cli_core_check(&g_core_iperf)) {
        (void)rtlnet_iperf_read_stats(RTLNET_PLAT_IPERF_BASE, &st);
        fmt_printf("iperf server on UDP port %u%s%s, reverse (-R) %s\n", (unsigned)st.udp_port,
                   st.rx_active ? ", receiving" : "", st.tx_active ? ", sending" : "",
                   st.reverse_allowed ? "allowed" : "off");
        fmt_printf("  Last flow       : %u datagrams, %u bytes (low word), lost %u, out of order %u, jitter %u.%04u us\n",
                   (unsigned)st.rx_datagrams, (unsigned)(uint32_t)st.rx_bytes, (unsigned)st.rx_lost,
                   (unsigned)st.rx_outoforder, (unsigned)(st.jitter_us16 / 16u),
                   (unsigned)((st.jitter_us16 % 16u) * 625u));
        fmt_printf("  Duration        : %u us, requested rate %u b/s, reverse datagrams %u, reports %u\n",
                   (unsigned)st.last_duration_us, (unsigned)st.req_rate_bps, (unsigned)st.tx_datagrams,
                   (unsigned)st.reports_sent);
    }
    rtlnet_tcp_iperf_status(&t);
    fmt_printf("TCP (firmware, lwIP)\n");
    fmt_printf("iperf server on TCP port %u: %s, %s; tests %u, refused %u\n", (unsigned)t.port,
               t.enabled ? "enabled" : "disabled",
               t.listening ? "listening" : (t.lwip_running ? "not listening" : "waiting for lwIP"), (unsigned)t.tests,
               (unsigned)t.rejected);
    cli_tcp_iperf_test_line("Last test       ", &t.last);
    if (t.prev.result != RTLNET_TCP_IPERF_NONE) {
        cli_tcp_iperf_test_line("Previous test   ", &t.prev);
    }
    fmt_printf("  Tests by way    : pc->board %u, reverse -R %u, tradeoff -r %u, dual -d %u\n",
               (unsigned)t.tests_dir[RTLNET_TCP_IPERF_DIR_RX], (unsigned)t.tests_dir[RTLNET_TCP_IPERF_DIR_REVERSE],
               (unsigned)t.tests_dir[RTLNET_TCP_IPERF_DIR_TRADEOFF], (unsigned)t.tests_dir[RTLNET_TCP_IPERF_DIR_DUAL]);
    return 0;
}

/**
 * @brief IPERF TCP ENABLE.
 * @param ctx Unused.
 * @return 0.
 */
int cli_iperf_tcp_enable(const MenuCommandContext *ctx)
{
    (void)ctx;
    netmgr_config()->tcp_iperf_enable = 1;
    netmgr_apply_tcp_iperf();
    return 0;
}

/**
 * @brief IPERF TCP DISABLE: the lwiperf server session ends.
 * @param ctx Unused.
 * @return 0.
 */
int cli_iperf_tcp_disable(const MenuCommandContext *ctx)
{
    (void)ctx;
    netmgr_config()->tcp_iperf_enable = 0;
    netmgr_apply_tcp_iperf();
    return 0;
}

/**
 * @brief IPERF TCP PORT [PORT].
 * @param ctx argv[0] = port 1..65535.
 * @return 0, or -1 for a bad port.
 */
int cli_iperf_tcp_port(const MenuCommandContext *ctx)
{
    uint32_t p;
    if (cli_parse_u32(ctx->argv[0], &p) != 0 || p == 0u || p > CLI_UDP_PORT_MAX) {
        return cli_bad_value("TCP port (1..65535)", ctx->argv[0]);
    }
    netmgr_config()->tcp_iperf_port = p;
    netmgr_apply_tcp_iperf();
    return 0;
}

/**
 * @brief PHY RESET: hardware reset of the PHY, then InitPHY again (RX delay,
 *        LEDs, EEE, advertisement); the link monitor reports the link going
 *        down and up.
 * @param ctx Unused.
 * @return 0, or -1 when the MDIO core is absent or InitPHY fails.
 */
int cli_phy_reset(const MenuCommandContext *ctx)
{
    int rc;
    (void)ctx;
    if (!cli_core_check(&g_core_mdio)) {
        return 0;
    }
    rc = netmgr_phy_reset();
    if (rc != NETMGR_PHY_OK) {
        fmt_printf("%% InitPHY failed (%d)\n", rc);
        return -1;
    }
    return 0;
}

/**
 * @brief SHOW SOCKETS: socket table from the hardware, UDP echo and the
 *        socket-layer counters.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_sockets(const MenuCommandContext *ctx)
{
    rtlnet_udp_socket_counters_t k;
    rtlnet_udp_echo_config_t ec;
    rtlnet_udp_echo_counters_t ek;
    char r[16];
    char mt[18];
    (void)ctx;
    if (!cli_core_check(&g_core_udp)) {
        return 0;
    }
    fmt_printf("Sock  State   Local  Remote           Port   Next-hop MAC       Conn  RX      TX      Drops\n");
    for (unsigned i = 0; i < NETMGR_NUM_SOCKETS; i++) {
        rtlnet_udp_socket_config_t sc;
        rtlnet_udp_socket_remote_t rm;
        rtlnet_udp_socket_sock_counters_t sk;
        if (rtlnet_udp_socket_get_config(RTLNET_PLAT_UDP_BASE, i, &sc) != 0 ||
            rtlnet_udp_socket_get_remote(RTLNET_PLAT_UDP_BASE, i, &rm) != 0 ||
            rtlnet_udp_socket_read_sock_counters(RTLNET_PLAT_UDP_BASE, i, &sk) != 0) {
            continue;
        }
        fmt_printf("%-4u  %-6s  %-5u  %-15s  %-5u  %s  %-4s  %-6u  %-6u  %u\n", i, sc.enabled ? "open" : "closed",
                   (unsigned)sc.local_port, cli_ipv4_text(rm.ip, r), (unsigned)rm.port, cli_mac_text(rm.mac, mt),
                   sc.connect_on_rx ? "yes" : "no", (unsigned)sk.rx_datagrams, (unsigned)sk.tx_datagrams,
                   (unsigned)(sk.rx_drops + sk.tx_drops));
    }
    (void)rtlnet_udp_socket_read_counters(RTLNET_PLAT_UDP_BASE, &k);
    fmt_printf("Socket layer      : rx %u, no socket %u, bad %u, fifo drops %u, tx frames %u, tx drops %u\n",
               (unsigned)k.rx_datagrams, (unsigned)k.rx_no_socket, (unsigned)k.rx_bad, (unsigned)k.rx_fifo_drops,
               (unsigned)k.tx_frames, (unsigned)k.tx_drops);
    if (cli_core_check(&g_core_echo) && rtlnet_udp_echo_get_config(RTLNET_PLAT_ECHO_BASE, &ec) == 0 &&
        rtlnet_udp_echo_read_counters(RTLNET_PLAT_ECHO_BASE, &ek) == 0) {
        fmt_printf("UDP echo          : %s on ", ec.enabled ? "enabled" : "disabled");
        if (ec.socket_any) {
            fmt_printf("any socket");
        } else {
            fmt_printf("socket %u", (unsigned)ec.socket);
        }
        fmt_printf(", echoed %u datagrams / %u bytes, discarded %u\n", (unsigned)ek.echoed_datagrams,
                   (unsigned)ek.echoed_bytes, (unsigned)ek.discarded);
    }
    return 0;
}

/**
 * @brief SHOW COUNTERS: frame counters of every core.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_counters(const MenuCommandContext *ctx)
{
    (void)ctx;
    if (cli_core_check(&g_core_mac)) {
        rtlnet_eth_mac_counters_t k;
        rtlnet_eth_mac_read_counters(RTLNET_PLAT_MAC_BASE, &k);
        fmt_printf("MAC               : rx good %u, rx bad %u, rx overflow %u, tx %u\n", (unsigned)k.rx_good,
                   (unsigned)k.rx_bad, (unsigned)k.rx_overflow, (unsigned)k.tx_frames);
    }
    if (cli_core_check(&g_core_prot)) {
        rtlnet_eth_protocol_counters_t k;
        rtlnet_eth_protocol_read_counters(RTLNET_PLAT_PROT_BASE, &k);
        fmt_printf("Protocol          : ingress %u, filtered %u, dropped %u, egress %u\n", (unsigned)k.ingress_frames,
                   (unsigned)k.ingress_filtered, (unsigned)k.ingress_dropped, (unsigned)k.egress_frames);
    }
    if (cli_core_check(&g_core_arp)) {
        rtlnet_arp_counters_t k;
        rtlnet_arp_read_counters(RTLNET_PLAT_ARP_BASE, &k);
        fmt_printf("ARP               : requests %u, replies %u, ignored %u\n", (unsigned)k.requests_for_us,
                   (unsigned)k.replies_sent, (unsigned)k.ignored);
    }
    if (cli_core_check(&g_core_icmp)) {
        rtlnet_icmp_counters_t k;
        rtlnet_icmp_read_counters(RTLNET_PLAT_ICMP_BASE, &k);
        fmt_printf("ICMP              : echo requests %u, replies %u, bad checksum %u, bad size %u (max payload %u)\n",
                   (unsigned)k.echo_requests, (unsigned)k.echo_replies, (unsigned)k.dropped_checksum,
                   (unsigned)k.dropped_size, (unsigned)rtlnet_icmp_get_max_payload(RTLNET_PLAT_ICMP_BASE));
    }
    if (cli_core_check(&g_core_dhcp)) {
        rtlnet_dhcp_counters_t k;
        (void)rtlnet_dhcp_read_counters(RTLNET_PLAT_DHCP_BASE, &k);
        fmt_printf("DHCP              : discover %u, offer %u, request %u, ack %u, nak %u\n", (unsigned)k.discovers_sent,
                   (unsigned)k.offers_rx, (unsigned)k.requests_sent, (unsigned)k.acks_rx, (unsigned)k.naks_rx);
    }
    if (cli_core_check(&g_core_iperf)) {
        rtlnet_iperf_stats_t st;
        (void)rtlnet_iperf_read_stats(RTLNET_PLAT_IPERF_BASE, &st);
        fmt_printf("iperf             : datagrams %u, lost %u, reports %u\n", (unsigned)st.rx_datagrams,
                   (unsigned)st.rx_lost, (unsigned)st.reports_sent);
    }
    if (cli_core_check(&g_core_udp)) {
        rtlnet_udp_socket_counters_t k;
        (void)rtlnet_udp_socket_read_counters(RTLNET_PLAT_UDP_BASE, &k);
        fmt_printf("UDP sockets       : rx %u, no socket %u, bad %u, tx %u, tx drops %u\n", (unsigned)k.rx_datagrams,
                   (unsigned)k.rx_no_socket, (unsigned)k.rx_bad, (unsigned)k.tx_frames, (unsigned)k.tx_drops);
    }
    if (cli_core_check(&g_core_echo)) {
        rtlnet_udp_echo_counters_t k;
        (void)rtlnet_udp_echo_read_counters(RTLNET_PLAT_ECHO_BASE, &k);
        fmt_printf("UDP echo          : echoed %u datagrams / %u bytes, discarded %u\n", (unsigned)k.echoed_datagrams,
                   (unsigned)k.echoed_bytes, (unsigned)k.discarded);
    }
    {
        const rtlnet_netif_stats_t *n = rtlnet_netif_stats();
        cpupath_cls_counters_t ck;
        rtlnet_tcp_echo_status_t e;
        fmt_printf("CPU path DMA      : rx %u (no pbuf %u, errors %u), tx %u (timeouts %u, errors %u)\n",
                   (unsigned)n->rx_frames, (unsigned)n->rx_no_pbuf, (unsigned)n->rx_errors, (unsigned)n->tx_frames,
                   (unsigned)n->tx_timeouts, (unsigned)n->tx_errors);
        if (cpupath_cls_counters(&ck) == CPUPATH_OK) {
            fmt_printf("Classifier        : frames %u, passed %u, dropped %u\n", (unsigned)ck.frames,
                       (unsigned)ck.passed, (unsigned)ck.dropped);
            fmt_printf("Storm control     : broadcasts seen %u, passed %u, dropped %u\n",
                       (unsigned)ck.pol_seen[CPUPATH_STORM_POLICER], (unsigned)ck.pol_passed[CPUPATH_STORM_POLICER],
                       (unsigned)ck.pol_dropped[CPUPATH_STORM_POLICER]);
        } else {
            fmt_printf("Classifier        : %s\n", cpupath_cls_present() ? "counters not readable" :
                       "not present in this build");
        }
        rtlnet_tcp_echo_status(&e);
        fmt_printf("TCP echo          : connections %u, bytes in %u, out %u\n", (unsigned)e.accepted,
                   (unsigned)e.bytes_rx, (unsigned)e.bytes_tx);
    }
    return 0;
}

/**
 * @brief The classifier protection profile as configuration commands (the four class policers).
 * @return None.
 */
static void cli_print_protect_config(void)
{
    protect_class_t pc;
    for (unsigned c = 0u; c < PROTECT_CLASSES; c++) {
        if (protect_class_get(c, &pc) == PROTECT_OK) {
            fmt_printf("classifier policer %s %u %u\n", protect_class_name(c), (unsigned)pc.limit_pkts,
                       (unsigned)pc.window_ms);
        }
    }
}

/**
 * @brief SHOW RUNNING-CONFIG: the running configuration as commands.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_running(const MenuCommandContext *ctx)
{
    const netmgr_config_t *c = netmgr_config();
    char a[16];
    char m[16];
    char mt[18];
    (void)ctx;
    fmt_printf("!\n! RTLNet running configuration\n!\ninterface eth0\n");
    fmt_printf(" speed %s\n", cli_speed_text(netmgr_adv_effective()));
    fmt_printf(" %sshutdown\n", c->shutdown ? "" : "no ");
    fmt_printf(" mac-address %s\n", cli_mac_text(c->mac, mt));
    if (c->static_ip != 0u) {
        fmt_printf(" ip address %s %s\n", cli_ipv4_text(c->static_ip, a), cli_ipv4_text(c->netmask, m));
    } else {
        fmt_printf(" no ip address\n");
    }
    fmt_printf("!\nip default-gateway %s\n!\n", cli_ipv4_text(c->gateway, a));
    fmt_printf("ip dhcp\n %sauto\n!\n", c->dhcp_auto ? "" : "no ");
    for (unsigned i = 0; i < NETMGR_NUM_SOCKETS; i++) {
        const netmgr_socket_cfg_t *k = &c->sock[i];
        if (!k->open && k->remote_ip == 0u && !k->connect_on_rx) {
            continue;
        }
        fmt_printf("socket %u\n", i);
        if (k->open) {
            fmt_printf(" open %u\n", (unsigned)k->local_port);
        }
        if (k->remote_ip != 0u) {
            fmt_printf(" remote %s %u %s\n", cli_ipv4_text(k->remote_ip, a), (unsigned)k->remote_port,
                       cli_mac_text(k->remote_mac, mt));
        }
        if (k->connect_on_rx) {
            fmt_printf(" connect-on-receive\n");
        }
        fmt_printf("!\n");
    }
    if (c->echo_socket < 0) {
        fmt_printf("echo socket any\n");
    } else {
        fmt_printf("echo socket %d\n", c->echo_socket);
    }
    fmt_printf("%secho enable\n", c->echo_enable ? "" : "no ");
    fmt_printf("iperf port %u\n!\n", (unsigned)c->iperf_port);
    fmt_printf("tcp echo port %u\ntcp echo %s\n!\n", (unsigned)c->tcp_echo_port, c->tcp_echo_enable ? "enable" : "disable");
    fmt_printf("iperf tcp port %u\niperf tcp %s\n!\n", (unsigned)c->tcp_iperf_port,
               c->tcp_iperf_enable ? "enable" : "disable");
    if ((rtlnet_offload_request() & RTLNET_OFFLOAD_TX_IP) == 0u) {
        fmt_printf("offload tx-ip off\n");
    }
    if ((rtlnet_offload_request() & RTLNET_OFFLOAD_TX_L4) == 0u) {
        fmt_printf("offload tx-l4 off\n");
    }
    if ((rtlnet_offload_request() & RTLNET_OFFLOAD_RX) == 0u) {
        fmt_printf("offload rx off\n");
    }
    /* ACK coalescing is on at boot (500 us, default limit): list it when it is off or configured differently. */
    if ((rtlnet_offload_feat()->present & RTLNET_OFFLOAD_FEAT_ACK) != 0u) {
        if ((rtlnet_offload_feat()->on & RTLNET_OFFLOAD_FEAT_ACK) == 0u) {
            fmt_printf("offload ack-coalesce off\n");
        } else if (rtlnet_offload_feat()->ack_timer_us != RTLNET_OFFLOAD_ACK_BOOT_TIMER_US ||
                   rtlnet_offload_feat()->ack_limit != RTLNET_OFFLOAD_ACK_BOOT_LIMIT) {
            fmt_printf("offload ack-coalesce on %u %u\n", (unsigned)rtlnet_offload_feat()->ack_timer_us,
                       (unsigned)rtlnet_offload_feat()->ack_limit);
        }
    }
    if ((rtlnet_offload_feat()->on & RTLNET_OFFLOAD_FEAT_BATCH) != 0u) {
        fmt_printf("offload rx-batch on %u %u\n", (unsigned)rtlnet_offload_feat()->bat_timer_us,
                   (unsigned)rtlnet_offload_feat()->bat_frames);
    }
    cli_print_protect_config();
    fmt_printf("end\n");
    return 0;
}

