/**
 * @brief Apply the PHY settings when the PHY is there.
 * @return 0, or -1 on a driver error.
 */
static int cli_apply_phy(void)
{
    if (!cli_config_core(&g_core_mdio)) {
        return 0;
    }
    if (!netmgr_present()->phy) {
        fmt_printf("%% PHY did not answer; setting kept in the running configuration\n");
        return 0;
    }
    return cli_rc("PHY configuration", netmgr_apply_phy());
}

/**
 * @brief SPEED [MBPS]: 10, 100 or auto, full duplex.
 *        Writes the one speed state (the advertised full-duplex set) and
 *        restarts auto-negotiation, so the last speed command always wins: auto advertises every full-duplex mode of the board
 *        (LINK_CAPS, best common rate), 10 and 100 advertise that one full-duplex mode.
 * @param ctx argv[0] = speed.
 * @return 0, or -1 for another value.
 */
int cli_if_speed(const MenuCommandContext *ctx)
{
    netmgr_config_t *c = netmgr_config();
    uint32_t adv;
    if (cli_word_is(ctx->argv[0], "auto")) {
        adv = netmgr_adv_supported();
    } else if (cli_word_is(ctx->argv[0], "10")) {
        adv = RTLNET_PHY_ADV_10F;
    } else if (cli_word_is(ctx->argv[0], "100")) {
        adv = RTLNET_PHY_ADV_100F;
    } else {
        return cli_bad_value("speed (10, 100, auto)", ctx->argv[0]);
    }
    if ((adv & netmgr_adv_supported()) == 0u) {
        fmt_printf("%% This board does not support %s Mb/s\n", ctx->argv[0]);
        return -1;
    }
    c->adv_mask = adv;
    return cli_apply_phy();
}

