/* ------------------------------------------------------------------------- */
/* CPU network path: lwIP, TCP echo, DMA, classifier                          */
/* ------------------------------------------------------------------------- */

/**
 * @brief Text of an InitLWIP() result.
 * @param rc RTLNET_LWIP_* code.
 * @return Description.
 */
static const char *cli_lwip_result(int rc)
{
    switch (rc) {
    case RTLNET_LWIP_UNCHANGED:    return "unchanged";
    case RTLNET_LWIP_STARTED:      return "started";
    case RTLNET_LWIP_RECONFIGURED: return "reconfigured";
    case RTLNET_LWIP_NO_PROTOCOL:  return "protocol core not present";
    case RTLNET_LWIP_NO_DMA:       return "AXI DMA not present";
    default:                       return "netif_add failed";
    }
}

/**
 * @brief SHOW TCP: lwIP netif as configured by InitLWIP, the RTL identity it
 *        follows, the TCP echo server, its connections and lwIP counters.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_tcp(const MenuCommandContext *ctx)
{
    rtlnet_lwip_status_t s;
    rtlnet_tcp_echo_status_t e;
    rtlnet_lwip_counters_t k;
    char a[16];
    char m[16];
    char g[16];
    char mt[18];
    unsigned listed = 0;
    (void)ctx;
    rtlnet_lwip_status(&s);
    rtlnet_tcp_echo_status(&e);
    fmt_printf("lwIP              : %s, link %s; InitLWIP %u calls, %u reconfigurations (MAC %u, address %u), last %s\n",
               s.running ? "running" : "not started", s.link_up ? "up" : "down", (unsigned)s.init_calls,
               (unsigned)s.reconfigs, (unsigned)s.mac_changes, (unsigned)s.addr_changes, cli_lwip_result(s.last_result));
    if (s.running) {
        uint8_t rmac[6];
        uint32_t rip = rtlnet_eth_protocol_get_effective_ip(RTLNET_PLAT_PROT_BASE);
        uint32_t rmask = rtlnet_eth_protocol_get_effective_mask(RTLNET_PLAT_PROT_BASE);
        uint32_t rgw = rtlnet_eth_protocol_get_effective_gateway(RTLNET_PLAT_PROT_BASE);
        int same = 1;
        rtlnet_eth_protocol_get_mac(RTLNET_PLAT_PROT_BASE, rmac);
        for (unsigned i = 0; i < 6u; i++) {
            same = same && (rmac[i] == s.mac[i]);
        }
        same = same && (rip == s.ip) && (rmask == s.mask) && (rgw == s.gw);
        fmt_printf("  Interface e0    : MAC %s, IPv4 %s mask %s gateway %s\n", cli_mac_text(s.mac, mt),
                   cli_ipv4_text(s.ip, a), cli_ipv4_text(s.mask, m), cli_ipv4_text(s.gw, g));
        fmt_printf("  RTL identity    : %s (protocol wrapper MAC and effective address)\n",
                   same ? "matches" : "DIFFERS, InitLWIP updates it on the next poll");
    }
    fmt_printf("TCP echo          : %s, port %u, %s\n", e.enabled ? "enabled" : "disabled", (unsigned)e.port,
               e.listening ? "listening" : (e.lwip_running ? "not listening" : "waiting for lwIP"));
    fmt_printf("  Connections     : active %u, accepted %u, refused %u, closed %u, aborted %u, write errors %u\n",
               (unsigned)e.active, (unsigned)e.accepted, (unsigned)e.refused, (unsigned)e.closed, (unsigned)e.aborted,
               (unsigned)e.write_errors);
    fmt_printf("  Bytes           : received %u, echoed %u\n", (unsigned)e.bytes_rx, (unsigned)e.bytes_tx);
    for (unsigned i = 0; i < RTLNET_TCP_ECHO_MAX_CONN; i++) {
        rtlnet_tcp_echo_conn_t cn;
        if (!rtlnet_tcp_echo_conn(i, &cn)) {
            continue;
        }
        if (listed++ == 0u) {
            fmt_printf("  Slot  Remote           Port   RX bytes    TX bytes    Queued  Age s  State\n");
        }
        fmt_printf("  %-4u  %-15s  %-5u  %-10u  %-10u  %-6u  %-5u  %s\n", i, cli_ipv4_text(cn.remote_ip, a),
                   (unsigned)cn.remote_port, (unsigned)cn.bytes_rx, (unsigned)cn.bytes_tx, (unsigned)cn.queued,
                   (unsigned)(cn.age_ms / 1000u), cn.closing ? "closing" : "open");
    }
    if (s.running) {
        rtlnet_lwip_counters(&k);
        fmt_printf("lwIP counters     : link rx %u tx %u drop %u; ARP rx %u tx %u; IP rx %u tx %u drop %u\n",
                   (unsigned)k.link_recv, (unsigned)k.link_xmit, (unsigned)k.link_drop, (unsigned)k.etharp_recv,
                   (unsigned)k.etharp_xmit, (unsigned)k.ip_recv, (unsigned)k.ip_xmit, (unsigned)k.ip_drop);
        fmt_printf("                    TCP rx %u tx %u drop %u err %u\n", (unsigned)k.tcp_recv,
                   (unsigned)k.tcp_xmit, (unsigned)k.tcp_drop, (unsigned)k.tcp_err);
        fmt_printf("lwIP memory       : heap used %u max %u of %u (err %u); pbuf pool used %u max %u of %u (err %u);"
                   " TCP PCB %u of %u, segments max %u\n",
                   (unsigned)k.mem_used, (unsigned)k.mem_max, (unsigned)k.mem_avail, (unsigned)k.mem_err,
                   (unsigned)k.pbuf_pool_used, (unsigned)k.pbuf_pool_max, (unsigned)k.pbuf_pool_avail,
                   (unsigned)k.pbuf_pool_err, (unsigned)k.tcp_pcb_used, (unsigned)k.tcp_pcb_avail,
                   (unsigned)k.tcp_seg_max);
    }
    return 0;
}

/**
 * @brief SHOW CPU-PATH: AXI DMA status and frame counters, the wrapper's
 *        CPU-path counters, the classifier state.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_cpu_path(const MenuCommandContext *ctx)
{
    const rtlnet_netif_stats_t *n = rtlnet_netif_stats();
    cpupath_wrapper_counters_t w;
    int rc;
    (void)ctx;
    fmt_printf("CPU network path (cpu_axis_ethernet_stream)\n");
    if (!rtlnet_netif_hw_present()) {
        fmt_printf("  AXI DMA         : not present at 0x%08X\n", (unsigned)RTLNET_PLAT_DMA_BASE);
    } else {
        fmt_printf("  AXI DMA         : 0x%08X, S2MM status 0x%08X, MM2S status 0x%08X, resets %u\n",
                   (unsigned)RTLNET_PLAT_DMA_BASE, (unsigned)rtlnet_netif_dma_sr(1), (unsigned)rtlnet_netif_dma_sr(0),
                   (unsigned)n->dma_resets);
    }
    fmt_printf("  DMA receive     : frames %u, bytes %u; dropped: no pbuf %u, runt %u, lwIP down %u; errors %u\n",
               (unsigned)n->rx_frames, (unsigned)n->rx_bytes, (unsigned)n->rx_no_pbuf, (unsigned)n->rx_runts,
               (unsigned)n->rx_unbound, (unsigned)n->rx_errors);
    fmt_printf("  DMA transmit    : frames %u, bytes %u; timeouts %u, too long %u, errors %u\n", (unsigned)n->tx_frames,
               (unsigned)n->tx_bytes, (unsigned)n->tx_timeouts, (unsigned)n->tx_too_long, (unsigned)n->tx_errors);
#if RTLNET_NETIF_PROFILE
    {
        /* Profile since the last CLEAR COUNTERS: busy = polls that delivered frames (lwIP and applications included). */
        uint32_t tpu = RTLNET_PLAT_TICKS_PER_US;
        uint32_t wall_ms = (plat_ticks() - n->prof_clear) / (tpu * 1000u);
        uint32_t busy_ms = n->prof_busy / (tpu * 1000u);
        uint32_t rxf = (n->rx_frames != 0u) ? n->rx_frames : 1u;
        uint32_t txf = (n->tx_frames != 0u) ? n->tx_frames : 1u;
        fmt_printf("  CPU profile     : wall %u ms, busy %u ms (%u%%), poll budget hit %u times\n", (unsigned)wall_ms,
                   (unsigned)busy_ms, (unsigned)((wall_ms != 0u) ? (busy_ms * 100u / wall_ms) : 0u),
                   (unsigned)n->rx_budget_hits);
        fmt_printf("  Per RX frame    : copy %u.%02u us, lwIP input %u.%02u us\n",
                   (unsigned)(n->prof_rx_copy / rxf / tpu), (unsigned)(n->prof_rx_copy / rxf % tpu),
                   (unsigned)(n->prof_rx_input / rxf / tpu), (unsigned)(n->prof_rx_input / rxf % tpu));
        fmt_printf("  Per TX frame    : copy %u.%02u us, DMA wait %u.%02u us, DMA start %u.%02u us\n",
                   (unsigned)(n->prof_tx_copy / txf / tpu), (unsigned)(n->prof_tx_copy / txf % tpu),
                   (unsigned)(n->prof_tx_wait / txf / tpu), (unsigned)(n->prof_tx_wait / txf % tpu),
                   (unsigned)(n->prof_tx_start / txf / tpu), (unsigned)(n->prof_tx_start / txf % tpu));
    }
#else
    fmt_printf("  CPU profile     : not built (RTLNET_NETIF_PROFILE 0); poll budget hit %u times\n",
               (unsigned)n->rx_budget_hits);
#endif
    rc = cpupath_wrapper_counters(&w);
    if (rc == CPUPATH_OK) {
        fmt_printf("  Wrapper         : CPU path %s, CPU FIFOs rx %u KiB tx %u KiB\n", w.enabled ? "enabled" : "disabled",
                   (unsigned)w.rx_fifo_kb, (unsigned)w.tx_fifo_kb);
        fmt_printf("  Wrapper RX      : delivered %u, to CPU %u, claimed by a leaf %u, CPU FIFO drops %u\n",
                   (unsigned)w.delivered, (unsigned)w.rx_frames, (unsigned)w.rx_claimed, (unsigned)w.rx_fifo_drops);
        fmt_printf("  Wrapper TX      : from CPU %u, discarded (path off) %u, rejected %u\n", (unsigned)w.tx_frames,
                   (unsigned)w.tx_discarded, (unsigned)w.tx_rejected);
    } else if (rc == CPUPATH_ABSENT) {
        fmt_printf("  Wrapper         : protocol core not present in this build\n");
    } else {
        fmt_printf("  Wrapper         : protocol core built without the CPU network path\n");
    }
    fmt_printf("  Classifier      : %s, mode %s\n", cpupath_cls_present() ? "present" : "not present in this build",
               cpupath_mode_name(cpupath_cls_config()->mode));
    return 0;
}

/**
 * @brief TCP ECHO ENABLE.
 * @param ctx Unused.
 * @return 0.
 */
int cli_tcp_echo_enable(const MenuCommandContext *ctx)
{
    (void)ctx;
    netmgr_config()->tcp_echo_enable = 1;
    netmgr_apply_tcp_echo();
    return 0;
}

/**
 * @brief TCP ECHO DISABLE: the listen PCB closes, open connections stay.
 * @param ctx Unused.
 * @return 0.
 */
int cli_tcp_echo_disable(const MenuCommandContext *ctx)
{
    (void)ctx;
    netmgr_config()->tcp_echo_enable = 0;
    netmgr_apply_tcp_echo();
    return 0;
}

/**
 * @brief TCP ECHO PORT [PORT].
 * @param ctx argv[0] = port 1..65535.
 * @return 0, or -1 for a bad port.
 */
int cli_tcp_echo_port(const MenuCommandContext *ctx)
{
    uint32_t p;
    if (cli_parse_u32(ctx->argv[0], &p) != 0 || p == 0u || p > CLI_UDP_PORT_MAX) {
        return cli_bad_value("TCP port (1..65535)", ctx->argv[0]);
    }
    netmgr_config()->tcp_echo_port = p;
    netmgr_apply_tcp_echo();
    return 0;
}

/**
 * @brief Print an on/off word.
 * @param on Nonzero for "on".
 * @return None.
 */
static void cli_print_onoff(int on)
{
    fmt_printf("%s", on ? "on" : "off");
}

/**
 * @brief The lwIP checksum flags as hardware (flag clear) or software (flag set) per protocol.
 * @param f Flags word.
 * @return None.
 */
static void cli_print_cs_flags(uint32_t f)
{
    fmt_printf("0x%04X  GEN ip %s udp %s tcp %s icmp %s | CHECK ip %s udp %s tcp %s icmp %s\n", (unsigned)f,
               (f & RTLNET_CS_GEN_IP) ? "sw" : "hw", (f & RTLNET_CS_GEN_UDP) ? "sw" : "hw",
               (f & RTLNET_CS_GEN_TCP) ? "sw" : "hw", (f & RTLNET_CS_GEN_ICMP) ? "sw" : "hw",
               (f & RTLNET_CS_CHECK_IP) ? "sw" : "hw", (f & RTLNET_CS_CHECK_UDP) ? "sw" : "hw",
               (f & RTLNET_CS_CHECK_TCP) ? "sw" : "hw", (f & RTLNET_CS_CHECK_ICMP) ? "sw" : "hw");
}

/**
 * @brief The receive features of the offload core in SHOW OFFLOAD: ACK coalescing and receive batching, their
 *        configuration and counters, and the netif side of batching. Prints nothing without the features.
 * @return None.
 */
static void cli_show_offload_features(void)
{
    const rtlnet_offload_feat_t *ft = rtlnet_offload_feat();
    const rtlnet_netif_stats_t *ns = rtlnet_netif_stats();
    rtlnet_txo_feat_counters_t fc;
    if (ft->present == 0u) {
        return;
    }
    if ((ft->present & RTLNET_OFFLOAD_FEAT_ACK) != 0u) {
        fmt_printf("  ACK coalescing  : %s, timer %u us, limit %u ACKs per forwarded ACK, %u flows\n",
                   (ft->on & RTLNET_OFFLOAD_FEAT_ACK) ? "on" : "off", (unsigned)ft->ack_timer_us, (unsigned)ft->ack_limit,
                   (unsigned)ft->ack_flows);
    }
    if ((ft->present & RTLNET_OFFLOAD_FEAT_BATCH) != 0u) {
        fmt_printf("  RX batching     : %s, timer %u us, at most %u frames and %u bytes (reserve %u), buffers %s\n",
                   (ft->on & RTLNET_OFFLOAD_FEAT_BATCH) ? "on" : "off", (unsigned)ft->bat_timer_us, (unsigned)ft->bat_frames,
                   (unsigned)ft->bat_bytes, (unsigned)ft->bat_reserve,
                   rtlnet_netif_rx_batch_active() ? "batch geometry" : "single-frame geometry");
    }
    if (rtlnet_offload_feat_counters(&fc) == RTLNET_TXO_OK) {
        if ((ft->present & RTLNET_OFFLOAD_FEAT_ACK) != 0u) {
            fmt_printf("  ACK counters    : candidates %u, dropped %u, forwarded %u, flushed by timer %u, limit %u, ordering %u\n",
                       (unsigned)fc.ack[RTLNET_TXO_CNT_ACK_CAND], (unsigned)fc.ack[RTLNET_TXO_CNT_ACK_DROPPED],
                       (unsigned)fc.ack[RTLNET_TXO_CNT_ACK_FWD], (unsigned)fc.ack[RTLNET_TXO_CNT_ACK_FL_TIMER],
                       (unsigned)fc.ack[RTLNET_TXO_CNT_ACK_FL_LIMIT], (unsigned)fc.ack[RTLNET_TXO_CNT_ACK_FL_ORDER]);
        }
        if ((ft->present & RTLNET_OFFLOAD_FEAT_BATCH) != 0u) {
            fmt_printf("  Batch counters  : batches %u, frames %u, closed by bytes %u, count %u, timer %u, other %u\n",
                       (unsigned)fc.bat[RTLNET_TXO_CNT_BAT_BATCHES], (unsigned)fc.bat[RTLNET_TXO_CNT_BAT_FRAMES],
                       (unsigned)fc.bat[RTLNET_TXO_CNT_BAT_CL_BYTES], (unsigned)fc.bat[RTLNET_TXO_CNT_BAT_CL_COUNT],
                       (unsigned)fc.bat[RTLNET_TXO_CNT_BAT_CL_TIMER], (unsigned)fc.bat[RTLNET_TXO_CNT_BAT_CL_OTHER]);
        }
    }
    if ((ft->present & RTLNET_OFFLOAD_FEAT_BATCH) != 0u) {
        fmt_printf("  Batch receive   : transfers walked %u, frames %u, most per transfer %u, bad %u, copied (no buffer "
                   "left) %u, no loan %u\n", (unsigned)ns->rx_batches, (unsigned)ns->rx_batch_frames,
                   (unsigned)ns->rx_batch_max, (unsigned)ns->rx_batch_bad, (unsigned)ns->rx_batch_copied,
                   (unsigned)ns->rx_batch_noloan);
    }
}

/**
 * @brief SHOW OFFLOAD: feature discovery, CTRL, the lwIP checksum flags (and
 *        a MISMATCH line when they disagree), counters, receive policy and
 *        the zero-copy build options.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_offload(const MenuCommandContext *ctx)
{
    static const char *const rx_state_name[] = { "off", "arming (no trailer seen yet)", "on", "draining (rx turned off)" };
    const rtlnet_features_t *f;
    const rtlnet_offload_state_t *st;
    rtlnet_txo_counters_t k;
    const rtlnet_netif_stats_t *ns = rtlnet_netif_stats();
    uint32_t ctrl = 0u;
    uint32_t status = 0u;
    uint32_t flags;
    uint32_t expect;
    (void)ctx;
    rtlnet_features_discover();
    f = rtlnet_features();
    st = rtlnet_offload_state();
    fmt_printf("Checksum offload (CPU path)\n");
    fmt_printf("  Discovery       : wrapper %s, CPU path %s, CPU_CAPS 0x%08X", f->wrapper_ok ? "ok" : "NOT FOUND",
               f->cpu_path ? "present" : "absent", (unsigned)f->cpu_caps);
    fmt_printf(" (classifier %s, offload TX %s, RX %s)\n", f->cls_advertised ? "advertised" : "no",
               f->tx_advertised ? "advertised" : "no", f->rx_advertised ? "advertised" : "no");
    fmt_printf("  Confirmed       : classifier %s, offload TX %s, offload RX %s%s\n", f->cls_present ? "yes" : "no",
               f->tx_present ? "yes" : "no", f->rx_present ? "yes" : "no",
               f->errors ? "  % MISMATCH found at boot, see the log" : "");
    if (!f->tx_present && !f->rx_present) {
        fmt_printf("  Offload         : not present in this build (lwIP computes and checks every checksum)\n");
        return 0;
    }
    (void)rtlnet_offload_ctrl_now(&ctrl);
    (void)rtlnet_offload_status(&status);
    fmt_printf("  Core            : CAPS 0x%08X at 0x%08X, TX buffer %u KB, STATUS 0x%08X (tx %s, rx %s)\n",
               (unsigned)f->block_caps, (unsigned)RTLNET_PLAT_TXO_BASE, (unsigned)rtlnet_offload_buffer_kb(), (unsigned)status,
               (status & RTLNET_TXO_STATUS_TX_IDLE) ? "idle" : "busy", (status & RTLNET_TXO_STATUS_RX_IDLE) ? "idle" : "busy");
    fmt_printf("  CTRL            : 0x%08X  tx-ip ", (unsigned)ctrl);
    cli_print_onoff((ctrl & RTLNET_OFFLOAD_TX_IP) != 0u);
    fmt_printf(", tx-l4 ");
    cli_print_onoff((ctrl & RTLNET_OFFLOAD_TX_L4) != 0u);
    fmt_printf(", rx ");
    cli_print_onoff((ctrl & RTLNET_OFFLOAD_RX) != 0u);
    fmt_printf("  (requested 0x%X, supported 0x%X)\n", (unsigned)rtlnet_offload_request(),
               (unsigned)rtlnet_offload_supported());
    fmt_printf("  RX trailers     : %s\n", rx_state_name[(unsigned)st->rx_state]);
    flags = rtlnet_lwip_get_checksum_ctrl();
    fmt_printf("  lwIP flags      : ");
    cli_print_cs_flags(flags);
    expect = rtlnet_offload_flags_for(ctrl, st->rx_state == RTLNET_RX_TRAILER_ON);
    if (flags != expect) {
        fmt_printf("  %% MISMATCH: lwIP flags 0x%04X, the CTRL read-back implies 0x%04X\n", (unsigned)flags,
                   (unsigned)expect);
    }
    if (rtlnet_offload_counters(&k) == RTLNET_TXO_OK) {
        fmt_printf("  TX counters     : frames %u, ip patched %u, l4 patched %u, skipped %u, malformed %u, dropped %u\n",
                   (unsigned)k.tx_frames, (unsigned)k.tx_ip_patched, (unsigned)k.tx_l4_patched, (unsigned)k.tx_skipped,
                   (unsigned)k.tx_malformed, (unsigned)k.tx_dropped);
        fmt_printf("  RX counters     : frames %u, verified %u, ip bad %u, l4 bad %u, unverified %u\n",
                   (unsigned)k.rx_frames, (unsigned)k.rx_verified, (unsigned)k.rx_ip_bad, (unsigned)k.rx_l4_bad,
                   (unsigned)k.rx_unverified);
    }
    fmt_printf("  RX policy       : trailers %u, passed verified %u, passed unverified %u, dropped bad ip %u, bad l4 %u, "
               "no trailer %u, raw %u\n", (unsigned)st->rx_trailer_frames, (unsigned)st->rx_verified,
               (unsigned)st->rx_unverified, (unsigned)st->rx_drop_ip, (unsigned)st->rx_drop_l4,
               (unsigned)st->rx_no_trailer, (unsigned)st->rx_raw);
    fmt_printf("  Build options   : zero-copy RX %s (%u buffers of %u bytes), zero-copy TX %s; frames sent in place %u, "
               "copied %u (chained pbufs %u, outside the buffer RAM %u), rx no buffer %u\n", RTLNET_NETIF_ZERO_COPY_RX ? "on" : "off", (unsigned)RTLNET_NETIF_RX_BUFS,
               (unsigned)RTLNET_NETIF_BUF_BYTES, RTLNET_NETIF_ZERO_COPY_TX ? "on" : "off", (unsigned)ns->tx_zero_copy,
               (unsigned)ns->tx_copied, (unsigned)ns->tx_copy_chained, (unsigned)ns->tx_copy_outside,
               (unsigned)ns->rx_no_buf);
    cli_show_offload_features();
    return 0;
}

/**
 * @brief ack-coalesce / rx-batch of the OFFLOAD command: configure and switch one receive feature of the core.
 *        rx-batch on switches the netif to the batch buffers first (then the hardware byte limit is the buffer
 *        size); rx-batch off switches the hardware off first, then the buffers back (when nothing is on loan).
 * @param ctx argv[0] = feature word, argv[1] = on or off, argv[2] = timer in microseconds, argv[3] = limit
 *            (ack-coalesce: ACKs dropped per forwarded ACK; rx-batch: frames per batch).
 * @param feat RTLNET_OFFLOAD_FEAT_ACK or RTLNET_OFFLOAD_FEAT_BATCH.
 * @param on 1 on, 0 off.
 * @return 0, or -1.
 */
static int cli_offload_feature(const MenuCommandContext *ctx, uint32_t feat, int on)
{
    uint32_t timer = RTLNET_OFFLOAD_KEEP;
    uint32_t limit = RTLNET_OFFLOAD_KEEP;
    int rc;
    if (ctx->argc > 2 && cli_parse_u32(ctx->argv[2], &timer) != 0) {
        return cli_bad_value("timer (microseconds)", ctx->argv[2]);
    }
    if (ctx->argc > 3 && cli_parse_u32(ctx->argv[3], &limit) != 0) {
        return cli_bad_value("limit", ctx->argv[3]);
    }
    if ((rtlnet_offload_feat()->present & feat) == 0u) {
        fmt_printf("%% This build has no such feature (see show offload)\n");
        return -1;
    }
    if (feat == RTLNET_OFFLOAD_FEAT_ACK) {
        rc = rtlnet_offload_ack_set(on, timer, limit);
    } else if (on) {
        int nrc = rtlnet_netif_set_rx_batch(1);
        if (nrc == RTLNET_NETIF_BATCH_BUSY) {
            fmt_printf("%% Receive buffers are in use: try again when the traffic has stopped\n");
            return -1;
        }
        rc = rtlnet_offload_batch_set(1, timer, limit, rtlnet_netif_rx_buf_bytes());
        if (rc != RTLNET_OFFLOAD_OK) {
            (void)rtlnet_netif_set_rx_batch(0);
        }
    } else {
        rc = rtlnet_offload_batch_set(0, RTLNET_OFFLOAD_KEEP, RTLNET_OFFLOAD_KEEP, RTLNET_OFFLOAD_KEEP);
        if (rc == RTLNET_OFFLOAD_OK && rtlnet_netif_set_rx_batch(0) == RTLNET_NETIF_BATCH_BUSY) {
            fmt_printf("%% Batching is off; the batch buffers stay until the frames in flight are consumed (repeat to retry)\n");
        }
    }
    if (rc == RTLNET_OFFLOAD_ERR_NEED_RX) {
        fmt_printf("%% The feature works on the receive trailer: turn the receive offload on first (offload rx on)\n");
    } else if (rc == RTLNET_OFFLOAD_ERR_ARG) {
        fmt_printf("%% Value out of range (timer 0..65535 us, ACK limit 0..255, frames per batch 0..%u)\n",
                   (unsigned)RTLNET_TXO_BATCH_MAX_FRAMES);
    } else if (rc == RTLNET_OFFLOAD_ERR_IO) {
        fmt_printf("%% CTRL did not read back as written\n");
    }
    return (rc == RTLNET_OFFLOAD_OK) ? 0 : -1;
}

/**
 * @brief OFFLOAD [WHAT] [STATE] {TIMER} {LIMIT} (config): request an offload on or off. WHAT
 *        is tx-ip, tx-l4, rx or all (the request is masked by what the
 *        bitstream has and applied through rtlnet_offload_apply: CTRL first
 *        or lwIP flags first, in the order that never loses a checksum), or
 *        ack-coalesce / rx-batch (receive features, optional TIMER microseconds and LIMIT).
 * @param ctx argv[0] = what, argv[1] = on or off, argv[2] = timer, argv[3] = limit (features only).
 * @return 0, or -1 for a bad word or a failed change.
 */
int cli_offload(const MenuCommandContext *ctx)
{
    uint32_t bits;
    uint32_t want = rtlnet_offload_request();
    int on;
    int rc;
    int feature = 0;
    uint32_t feat = 0u;
    if (cli_word_is(ctx->argv[0], "tx-ip")) {
        bits = RTLNET_OFFLOAD_TX_IP;
    } else if (cli_word_is(ctx->argv[0], "tx-l4")) {
        bits = RTLNET_OFFLOAD_TX_L4;
    } else if (cli_word_is(ctx->argv[0], "rx")) {
        bits = RTLNET_OFFLOAD_RX;
    } else if (cli_word_is(ctx->argv[0], "all")) {
        bits = RTLNET_OFFLOAD_ALL;
    } else if (cli_word_is(ctx->argv[0], "ack-coalesce")) {
        bits = 0u;
        feature = 1;
        feat = RTLNET_OFFLOAD_FEAT_ACK;
    } else if (cli_word_is(ctx->argv[0], "rx-batch")) {
        bits = 0u;
        feature = 1;
        feat = RTLNET_OFFLOAD_FEAT_BATCH;
    } else {
        return cli_bad_value("offload (tx-ip, tx-l4, rx, all, ack-coalesce, rx-batch)", ctx->argv[0]);
    }
    if (cli_word_is(ctx->argv[1], "on")) {
        on = 1;
    } else if (cli_word_is(ctx->argv[1], "off")) {
        on = 0;
    } else {
        return cli_bad_value("state (on, off)", ctx->argv[1]);
    }
    rtlnet_features_discover();
    if (feature) {
        return cli_offload_feature(ctx, feat, on);
    }
    if (ctx->argc > 2) {
        fmt_printf("%% The timer and limit arguments belong to ack-coalesce and rx-batch\n");
        return -1;
    }
    if ((bits & rtlnet_offload_supported()) == 0u) {
        fmt_printf("%% This build has no such offload (see show offload)\n");
        return -1;
    }
    want = on ? (want | bits) : (want & ~bits);
    rc = rtlnet_offload_apply(want);
    if (rc == RTLNET_OFFLOAD_ERR_TIMEOUT) {
        fmt_printf("%% The transmit offload did not go idle: left on, lwIP checksums restored\n");
    } else if (rc == RTLNET_OFFLOAD_ERR_IO) {
        fmt_printf("%% CTRL did not read back as written\n");
    }
    return (rc == RTLNET_OFFLOAD_OK) ? 0 : -1;
}

/* ------------------------------------------------------------------------- */
/* Classifier protection profile                                             */
/* ------------------------------------------------------------------------- */

/**
 * @brief SHOW CLASSIFIER: the built classifier (sizes, RAM style, latency), its mode, the protection profile
 *        and, per traffic class, the policer limit, window and counters.
 * @param ctx Unused.
 * @return 0.
 */
int cli_show_classifier(const MenuCommandContext *ctx)
{
    protect_info_t info;
    cpupath_cls_counters_t ck;
    protect_class_t pc;
    (void)ctx;
    fmt_printf("Classifier (CPU path)\n");
    if (protect_info(&info) != PROTECT_OK || !info.valid) {
        fmt_printf("  Not present in this build\n");
        return 0;
    }
    fmt_printf("  Build           : %u table entries, %u tuples, %u rules, %u policers, %u lanes, %u bytes matched, "
               "%s RAM\n", (unsigned)info.table_entries, (unsigned)info.tuple_entries, (unsigned)info.num_rules,
               (unsigned)info.num_policers, (unsigned)info.table_lanes, (unsigned)info.match_depth_bytes,
               info.ram_distributed ? "distributed" : "block");
    fmt_printf("  Latency         : %u beats (verdict %u)\n", (unsigned)info.delay_beats,
               (unsigned)info.verdict_latency);
    fmt_printf("  Mode            : %s\n", cpupath_mode_name(info.mode));
    fmt_printf("  Profile         : %s\n", info.installed ?
               "protection profile installed: everything passes except the classes below" :
               "protection profile NOT installed (build too small): broadcast storm limiter only");
    if (cpupath_cls_counters(&ck) == CPUPATH_OK) {
        fmt_printf("  Counters        : frames %u, passed %u, dropped %u (policers %u, mode %u, overrun %u)\n",
                   (unsigned)ck.frames, (unsigned)ck.passed, (unsigned)ck.dropped, (unsigned)ck.police_dropped,
                   (unsigned)ck.mode_dropped, (unsigned)ck.overrun_dropped);
    }
    if (!info.installed) {
        return 0;
    }
    fmt_printf("  Class      Limit / window      Seen    Passed   Dropped  Polices\n");
    for (unsigned c = 0u; c < PROTECT_CLASSES; c++) {
        if (protect_class_get(c, &pc) != PROTECT_OK) {
            fmt_printf("  %% class %s not readable\n", protect_class_name(c));
            continue;
        }
        fmt_printf("  %-9s %6u / %5u ms %9u %9u %9u  %s%s\n", protect_class_name(c), (unsigned)pc.limit_pkts,
                   (unsigned)pc.window_ms, (unsigned)pc.seen, (unsigned)pc.passed, (unsigned)pc.dropped,
                   protect_class_text(c), pc.enabled ? "" : " (policer off)");
    }
    return 0;
}

/**
 * @brief CLASSIFIER POLICER [CLASS] [FRAMES] [WINDOW-MS] (config): the number of frames of one traffic class the
 *        classifier passes to the CPU per window; the rest of the window's frames of that class are dropped.
 * @param ctx argv[0] = class (broadcast, udp, arp, icmp), argv[1] = frames 0..100000, argv[2] = window in ms 1..60000.
 * @return 0, or -1 for a bad word or a failed change.
 */
int cli_classifier_policer(const MenuCommandContext *ctx)
{
    uint32_t frames;
    uint32_t window;
    int cls = protect_class_find(ctx->argv[0]);
    int rc;
    if (cls < 0) {
        return cli_bad_value("class (broadcast, udp, arp, icmp)", ctx->argv[0]);
    }
    if (cli_parse_u32(ctx->argv[1], &frames) != 0 || frames > PROTECT_LIMIT_MAX) {
        return cli_bad_value("frames per window (0..100000)", ctx->argv[1]);
    }
    if (cli_parse_u32(ctx->argv[2], &window) != 0 || window == 0u || window > PROTECT_WINDOW_MAX_MS) {
        return cli_bad_value("window in ms (1..60000)", ctx->argv[2]);
    }
    rc = protect_set((unsigned)cls, frames, window);
    if (rc != PROTECT_OK) {
        fmt_printf("%% %s\n", protect_result_text(rc));
        return -1;
    }
    return 0;
}
